import{_ as o,o as t,c as s,a3 as a}from"./chunks/framework.DAK02U1-.js";const u=JSON.parse('{"title":"Vendor SDKs","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Vendor SDKs | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/xclang/design/vendor-sdks"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/xclang/design/vendor-sdks"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/design/vendor-sdks"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/design/vendor-sdks"}]]},"headers":[],"relativePath":"xclang/design/vendor-sdks.md","filePath":"en/xclang/design/vendor-sdks.md","lastUpdated":1791227177000}'),n={name:"xclang/design/vendor-sdks.md"};function i(d,e,r,c,h,l){return t(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="vendor-sdks" tabindex="-1">Vendor SDKs <a class="header-anchor" href="#vendor-sdks" aria-label="Permalink to &quot;Vendor SDKs&quot;">​</a></h1><p>Some targets need an SDK only its vendor may distribute: Apple&#39;s for macOS, Microsoft&#39;s MSVC libraries and Windows SDK for the MSVC ABI. xclang never redistributes them. The user fetches them from the vendor, by a pinned version and digest, after accepting the vendor&#39;s license, and xclang&#39;s tests fetch them the same way. The command that does it, <code>xclang sdk fetch</code>, is built and tested by CI but is in no release yet (<a href="./../reference/xclang-command">the xclang command</a>).</p><h2 id="why-fetch-not-ship" tabindex="-1">Why fetch, not ship <a class="header-anchor" href="#why-fetch-not-ship" aria-label="Permalink to &quot;Why fetch, not ship&quot;">​</a></h2><p>Apple&#39;s SDK agreement and Microsoft&#39;s Visual Studio license allow use, not redistribution. A toolchain that bundles them, or a Docker image that contains them, passes them on; cross-rs, for one, provides no images for Apple targets &quot;due to licensing reasons&quot; and leaves building one to the user. xclang goes the other way: it downloads from the vendor&#39;s own servers, so each user gets the SDK from the vendor under the vendor&#39;s terms, and xclang&#39;s archives stay free to share.</p><p>What that means for the user:</p><ul><li><code>xclang sdk fetch</code> prints the vendor&#39;s license terms and stops, until given <code>--accept-license</code>.</li><li>Apple&#39;s terms allow use of the SDK on Apple hardware. Building for macOS from Linux or Windows with it is the user&#39;s decision under those terms; xclang does not make it for them.</li><li>Versions are pinned: <code>cli/sdk-versions.json</code>, built into the program, lists every version the vendors offer with sizes and sha256, and presets that match GitHub&#39;s runner images (<code>macos-latest</code>, <code>windows-2022</code>, ...), so a cross build gets what a workflow on that image gets.</li></ul><h2 id="apple-s-sdk-without-xcode" tabindex="-1">Apple&#39;s SDK without Xcode <a class="header-anchor" href="#apple-s-sdk-without-xcode" aria-label="Permalink to &quot;Apple&#39;s SDK without Xcode&quot;">​</a></h2><p>The macOS SDK comes in Apple&#39;s Command Line Tools package, on <code>swcdn.apple.com</code>, found through Apple&#39;s software update catalogs, with no Apple ID. The package is a xar archive whose payload is pbzx (a stream of xz chunks) holding a cpio archive; xclang reads all three with its own code, a few hundred lines, so it works on every host without macOS tools. Man pages, tools and Perl are left out: 62 MB downloaded, 610 MB unpacked.</p><p><strong>The iOS family is a hard limit.</strong> The SDKs for iOS, tvOS, watchOS, visionOS and their simulators come only with full Xcode, downloaded with an Apple ID. No unattended fetch can get them, which is why those targets are in research and likely to need their runtimes built on demand.</p><h2 id="microsoft-s-sdk-without-visual-studio" tabindex="-1">Microsoft&#39;s SDK without Visual Studio <a class="header-anchor" href="#microsoft-s-sdk-without-visual-studio" aria-label="Permalink to &quot;Microsoft&#39;s SDK without Visual Studio&quot;">​</a></h2><p>MSVC&#39;s CRT and STL come from Visual Studio&#39;s own <code>.vsix</code> packages, named in its channel manifest, and the Windows SDK from NuGet&#39;s <code>Microsoft.Windows.SDK.CPP</code> packages. Both are zip archives. The usual route, Visual Studio&#39;s installer or the SDK&#39;s MSI and CAB files, needs Windows or tools that read MSI and CAB; zips are read by xclang&#39;s own code on every host. The files are laid out as Visual Studio installs them, for <code>/winsysroot</code>. Against xwin, which unpacks the MSI and CAB route, nothing these builds need was missing, and xwin has no macOS or Windows-on-Arm binaries, which xclang needed. 600 MB is downloaded for x64 and arm64, 1.8 GB unpacked.</p><p>On a case-sensitive file system, links are added for the spellings Windows code uses (<code>windows.h</code>, <code>WinBase.h</code> as <code>winbase.h</code>, <code>LIBCMT.lib</code>, ...): 3.6k of them, so code written on Windows builds unchanged.</p><h2 id="tested-by" tabindex="-1">Tested by <a class="header-anchor" href="#tested-by" aria-label="Permalink to &quot;Tested by&quot;">​</a></h2><p>cli.yml fetches both SDKs on every host, compiles C, C++ and Objective-C programs against them there, and runs the programs on macOS and Windows runners. tests/cargo.ts builds xclang&#39;s own Rust command for macOS and MSVC targets from Linux with them (<a href="./../integrations/cargo">Rust and cargo</a>).</p>',14)])])}const m=o(n,[["render",i]]);export{u as __pageData,m as default};
